import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def to_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        try:
            return openpyxl.utils.datetime.from_excel(value).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

current_date = to_date(vws["E4"].value)
if current_date is None:
    current_date = date.today()

best_date = None
best_value = None

for row in range(5, 17):
    d = to_date(vws.cell(row=row, column=1).value)
    v = vws.cell(row=row, column=2).value

    if d is None or v is None:
        continue

    if best_date is None or d > best_date:
        if d <= current_date:
            best_date = d
            best_value = v

if best_value is None:
    best_value = vws["B5"].value

ws["E5"] = best_value
wb.save(OUT)

print("current_date:", current_date)
print("best_date:", best_date)
print("E5:", best_value)
